{
  "backend": {
    "name": "github",
    "repo": "YOUR_GITHUB_OWNER/YOUR_REPOSITORY",
    "branch": "main"
  },
  "media_folder": "src/assets",
  "public_folder": "/src/assets",
  "output": {
    "omit_empty_optional_fields": true,
    "encode_file_path": true
  },
  "collections": [
    {
      "name": "posts",
      "label": "Posts",
      "folder": "src/content/posts",
      "create": true,
      "extension": "md",
      "format": "yaml-frontmatter",
      "slug": "{{slug}}",
      "media_folder": "/src/assets",
      "public_folder": "../../assets",
      "fields": [
        { "name": "title", "label": "Title", "widget": "string" },
        { "name": "description", "label": "Description", "widget": "text" },
        { "name": "publishedAt", "label": "Publication date", "widget": "datetime", "date_format": "YYYY-MM-DD", "time_format": false, "format": "YYYY-MM-DD" },
        { "name": "readingMinutes", "label": "Reading time (minutes)", "widget": "number", "value_type": "int", "min": 1, "max": 60, "step": 1, "required": false, "hint": "Optional whole minutes from 1 to 60." },
        { "name": "draft", "label": "Draft", "widget": "boolean", "default": false, "required": false },
        { "name": "hero", "label": "Hero image", "widget": "image", "required": false },
        { "name": "heroAlt", "label": "Hero image description", "widget": "string", "required": false, "hint": "Required when a hero image is selected. The site build validates this relationship." },
        { "name": "body", "label": "Body", "widget": "markdown" }
      ]
    }
  ]
}

import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';

const posts = defineCollection({
  loader: glob({ base: './src/content/posts', pattern: '**/*.md' }),
  schema: ({ image }) => z.object({
    title: z.string().trim().min(1),
    description: z.string().trim().min(1),
    publishedAt: z.coerce.date(),
    readingMinutes: z.number().int().min(1).max(60).optional(),
    draft: z.boolean().default(false),
    hero: image().optional(),
    heroAlt: z.string().trim().optional(),
  }).superRefine((post, context) => {
    if (post.hero && !post.heroAlt) context.addIssue({ code: 'custom', path: ['heroAlt'], message: 'Describe the meaningful hero image.' });
  }),
});

export const collections = { posts };

---
import type { CollectionEntry } from 'astro:content';
import { render } from 'astro:content';
import Base from '../../layouts/Base.astro';
import Section from '../../components/Section.astro';
import Container from '../../components/Container.astro';
import RichText from '../../components/RichText.astro';
import ResponsiveImage from '../../components/ResponsiveImage.astro';
import { publishedPosts } from '../../lib/posts';

export async function getStaticPaths() {
  return (await publishedPosts()).map(post => ({ params: { id: post.id }, props: { post } }));
}
interface Props { post: CollectionEntry<'posts'>; }
const { post } = Astro.props;
const { Content } = await render(post);
const imageTypes: Record<string, string> = { jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png', webp: 'image/webp', avif: 'image/avif', gif: 'image/gif', svg: 'image/svg+xml', tiff: 'image/tiff' };
const image = post.data.hero ? { src: post.data.hero.src, alt: post.data.heroAlt, width: post.data.hero.width, height: post.data.hero.height, mimeType: imageTypes[post.data.hero.format] } : undefined;
---
<Base title={post.data.title} description={post.data.description} pageType="article" publishedAt={post.data.publishedAt} image={image}>
  <Section labelledBy="post-title"><Container breakout class="flow">
    <header class="article-stack"><h1 id="post-title">{post.data.title}</h1><p>{post.data.description}</p>
      <time datetime={post.data.publishedAt.toISOString()}>{post.data.publishedAt.toLocaleDateString('en-GB', { timeZone: 'UTC', year: 'numeric', month: 'long', day: 'numeric' })}</time>
      {post.data.readingMinutes !== undefined && <p>{post.data.readingMinutes} min read</p>}
    </header>
    {post.data.hero && <figure class="content--feature"><ResponsiveImage src={post.data.hero} alt={post.data.heroAlt!} loading="eager" fetchpriority="high" /></figure>}
    <RichText><Content /></RichText>
  </Container></Section>
</Base>

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';

test('Sveltia form, frontmatter and native image paths match the Astro collection', () => {
  const config = JSON.parse(fs.readFileSync('public/admin/config.yml', 'utf8'));
  const schema = fs.readFileSync('src/content.config.ts', 'utf8');
  const posts = config.collections.find(c => c.name === 'posts');
  assert.equal(config.backend.name, 'github');
  assert.match(config.backend.repo, /^[\w.-]+\/[\w.-]+$/);
  assert.equal(config.output.omit_empty_optional_fields, true);
  assert.equal(config.output.encode_file_path, true);
  assert.ok(config.public_folder.startsWith('/'), 'Sveltia requires an absolute global public_folder; collection paths may be relative');
  assert.equal(posts.folder, 'src/content/posts');
  assert.equal(posts.create, true);
  assert.equal(posts.format, 'yaml-frontmatter');
  assert.equal(posts.extension, 'md');
  const widgets = { title: 'string', description: 'text', publishedAt: 'datetime', readingMinutes: 'number', draft: 'boolean', hero: 'image', heroAlt: 'string', body: 'markdown' };
  assert.deepEqual(posts.fields.map(f => f.name).sort(), Object.keys(widgets).sort());
  for (const field of posts.fields) {
    assert.equal(field.widget, widgets[field.name]);
    if (field.name !== 'body') assert.match(schema, new RegExp(`\\b${field.name}:`));
  }
  for (const name of ['readingMinutes', 'hero', 'heroAlt', 'draft']) assert.equal(posts.fields.find(f => f.name === name).required, false);
  const readingMinutes = posts.fields.find(f => f.name === 'readingMinutes');
  assert.deepEqual({ value_type: readingMinutes.value_type, min: readingMinutes.min, max: readingMinutes.max, step: readingMinutes.step }, { value_type: 'int', min: 1, max: 60, step: 1 });
  assert.equal(posts.fields.find(f => f.name === 'draft').default, false);
  assert.match(schema, /hero && !post.heroAlt/);
  assert.match(schema, /readingMinutes: z\.number\(\)\.int\(\)\.min\(1\)\.max\(60\)\.optional\(\)/);
  const reference = posts.public_folder + '/pilot-grid.jpg';
  assert.equal(path.posix.normalize(path.posix.join(posts.folder, reference)), 'src/assets/pilot-grid.jpg');
  assert.equal(posts.media_folder, '/src/assets');
  assert.ok(fs.existsSync(posts.media_folder.slice(1) + '/pilot-grid.jpg'));
  assert.match(fs.readFileSync('src/content/posts/welcome.md', 'utf8'), /hero:.*\.\.\/\.\.\/assets\/pilot-grid\.jpg/);
  const html = fs.readFileSync('public/admin/index.html', 'utf8');
  assert.match(html, /@sveltia\/cms@\d+\.\d+\.\d+\/dist\/sveltia-cms\.js/);
  assert.match(html, /integrity="sha384-[A-Za-z0-9+/=]+" crossorigin="anonymous"/);
  const scriptURL = html.match(/<script[^>]*src="([^"]+)"/)?.[1];
  assert.match(scriptURL, /^https:\/\/unpkg\.com\/@sveltia\/cms@\d+\.\d+\.\d+\/dist\/sveltia-cms\.js$/);
  assert.ok(!/client_secret|access_token/.test(JSON.stringify(config)));
});
